T("Accept only ordinary party invitations from the relationship types you select. Invites remain manual in combat, while grouped, during queue-loss or quest-session confirmations, or when Blizzard asks you to choose a role. The native popup handles the final action.", "Nimmt nur gewöhnliche Gruppeneinladungen aus den gewählten Vertrauensgruppen an. Im Kampf, innerhalb einer Gruppe, bei drohendem Verlust einer Warteschlange, bei Questgruppen-Bestätigungen oder bei einer Rollenauswahl bleiben Einladungen manuell. Der Blizzard-Dialog führt die Annahme aus.")
T("Accept ordinary party invites from selected friends or guild members when no queue or confirmation would be lost.", "Nimmt gewöhnliche Gruppeneinladungen von ausgewählten Freunden oder Gildenmitgliedern an, wenn dadurch keine Warteschlange oder Bestätigung verloren geht.")
