T("Applies at login and when a specialization change brings this role. A Mythic+ meter keeps its window during a keystone.", "Wird beim Einloggen und beim Wechsel zu dieser Rolle durch einen Spezialisierungswechsel angewendet. Ein Mythisch+-Meter behält sein Fenster während eines Schlüsselsteins.")
