T("Apply a graphics preset once. Balanced changes your general settings and keeps your separate raid settings.\nRaid / Dungeon changes only the separate instance settings and enables them.\nTextures, particle density and outlines stay as you set them; projected textures stay on. Unsupported settings are skipped.\nSharpening, contrast and audio reverb are optional and apply globally.\nYour originals are saved outside profiles. Restore keeps later manual changes. FPS gains depend on your hardware and the scene.", "Wende ein Grafikpreset einmalig an. Ausgewogen ändert die allgemeinen Einstellungen und behält deine separaten Raid-Einstellungen bei.\nSchlachtzug / Dungeon ändert nur die separaten Instanzeinstellungen und aktiviert sie.\nTexturen, Partikeldichte und Konturen bleiben wie eingestellt; projizierte Texturen bleiben an. Nicht unterstützte Einstellungen werden übersprungen.\nNachschärfung, Kontrast und Audiohall sind optional und gelten global.\nDeine ursprünglichen Werte werden außerhalb der Profile gesichert. Wiederherstellen behält spätere manuelle Änderungen bei. Der FPS-Gewinn hängt von deiner Hardware und der Szene ab.")
