T("At a trainer, review the count and combined gold cost before buying. The button learns only abilities already available at confirmation, checks each step again, and stops when the trainer closes, combat starts or the list changes. Profession choices and rank steps stay manual.", "Prüfe beim Lehrer vor dem Kauf die Anzahl und die gesamten Goldkosten. Der Knopf erlernt nur Fähigkeiten, die beim Bestätigen bereits verfügbar sind, prüft jeden Schritt erneut und stoppt, wenn sich das Lehrerfenster schließt, ein Kampf beginnt oder sich die Liste ändert. Berufsentscheidungen und Rangstufen bleiben manuell.")
