T("Blizzard's Cooldown Manager stops completely. While your MSUF frames follow its bars, MSUF keeps it running invisibly.", "Blizzards Cooldown-Manager stoppt vollständig. Solange deine MSUF-Frames seinen Leisten folgen, lässt MSUF ihn unsichtbar weiterlaufen.")
T("Blizzard's aggro, target, focus and soft target signals.", "Blizzards Aggro-, Ziel-, Fokus- und Soft-Target-Signale.")
T("Blizzard's bars keep running, invisible, so frames that other addons attach to them stay in place.", "Blizzards Leisten laufen unsichtbar weiter, damit Frames, die andere Addons daran anheften, an ihrem Platz bleiben.")
T("Blizzard's combined switch for pets, guardians and totems. The separate choices set each kind on its own.", "Blizzards gemeinsamer Schalter für Begleiter, Wächter und Totems. Mit den einzelnen Optionen stellst du jede Art separat ein.")
