T("Blizzard's distance and stacking options. Keep Blizzard setting changes nothing; other choices return to Blizzard's value when the skin turns off.", "Blizzards Optionen für Entfernung und Stapelung. Blizzard-Einstellung beibehalten ändert nichts; die anderen Optionen stellen beim Deaktivieren des Skins Blizzards Wert wieder her.")
T("Blizzard's entry for this spell is already on this bar.", "Blizzards Eintrag für diesen Zauber ist bereits auf dieser Leiste.")
T("Blizzard's list has too many entries for one bar.", "Blizzards Liste hat zu viele Einträge für eine Leiste.")
T("Blizzard's original Micro Bar and buttons. Use Blizzard Edit Mode to move it.", "Blizzards originales Mikromenü mit seinen Buttons. Verschiebe es im Blizzard-Bearbeitungsmodus.")
T("Blizzard's own buttons stay functional. The row is their starting position; drag each icon freely in the preview.", "Blizzards eigene Buttons bleiben funktionsfähig. Die Reihe ist ihre Startposition; ziehe jedes Symbol in der Vorschau frei.")
T("Blizzard's own cooldown swipe fills the ring: the global cooldown after each ability, and casts or channels while they run. A cast takes the place of the global cooldown until it ends; the bright edge marks how far the cast has come.", "Blizzards eigene Abklingzeit-Animation füllt den Ring: die globale Abklingzeit nach jeder Fähigkeit sowie Zauber und kanalisierte Zauber, solange sie laufen. Ein Zauber ersetzt die globale Abklingzeit, bis er endet; der helle Rand zeigt, wie weit der Zauber ist.")
T("Blizzard's own icons and castbar details.", "Blizzards eigene Symbole und Zauberleisten-Details.")
T("Blizzard's own nameplate options. Keep Blizzard setting changes nothing; other choices go back to Blizzard's value when the skin turns off.", "Blizzards eigene Namensplaketten-Optionen. Blizzard-Einstellung behalten ändert nichts; andere Werte kehren beim Ausschalten des Skins zu Blizzards Wert zurück.")
