T("Bounded named-root traversal\nDedicated visual-only Edit Mode coverage\nExplicit secure controls remain untouched\nBlizzard frames keep their parents and scripts; only Suite-made selection indicators move\nNo polling or tickers; OnUpdate runs only while a window corner is dragged", "Begrenzte Durchsuchung benannter Wurzelfenster\nEigene, rein optische Abdeckung des Bearbeitungsmodus\nAusdrücklich geschützte Bedienelemente bleiben unberührt\nBlizzard-Frames behalten Elternframes und Skripte; nur Suite-eigene Auswahlanzeigen wechseln den Elternframe\nKein Polling, keine Ticker; OnUpdate läuft nur, während eine Fensterecke gezogen wird")
