T("Brings back the spells you removed from the built-in bars, on every bar, for this specialization. You can undo it.", "Holt die Zauber zurück, die du aus den eingebauten Leisten entfernt hast – auf jeder Leiste, für diese Spezialisierung. Du kannst das rückgängig machen.")
