T("Bubbles outside instances can take the MSUF look; Blizzard locks the ones inside instances. Each source keeps Blizzard's look or uses the MSUF one: the shared look or its own font, size, colors, spacing and width. A bubble is matched to the line it shows right after that line arrives. Turning bubbles off inside instances uses Blizzard's bubble settings and gives them back when you leave or turn it off.", "Sprechblasen außerhalb von Instanzen können den MSUF-Look erhalten; die in Instanzen sperrt Blizzard. Jede Quelle behält Blizzards Look oder nutzt den von MSUF: den gemeinsamen Look oder eigene Schrift, Größe, Farben, Abstände und Breite. Eine Sprechblase wird der Zeile zugeordnet, die sie zeigt, direkt nachdem diese Zeile eintrifft. Sprechblasen in Instanzen auszuschalten nutzt Blizzards Sprechblaseneinstellungen und gibt sie zurück, wenn du die Instanz verlässt oder die Option ausschaltest.")
