T("Center keeps the whole visible cooldown row centered as icons appear or disappear. Enable Keep first icon centered for alternating growth around the first icon. Buff icons then keep fixed places, with gaps for inactive buffs. Attach the bar to another bar or to your player frame; Gap controls the space between them.", "Mitte hält die gesamte sichtbare Abklingzeit-Reihe mittig, wenn Symbole erscheinen oder verschwinden. Aktiviere Erstes Symbol mittig halten, damit weitere Symbole abwechselnd um das erste wachsen. Buff-Symbole behalten dann feste Plätze; inaktive Buffs hinterlassen Lücken. Verankere die Leiste an einer anderen Leiste oder an deinem Spielerfenster; Abstand legt den Zwischenraum fest.")
