T("Choose a smaller stack size and make sure the item is unlocked, your cursor is empty and you are out of combat.", "Wähle eine kleinere Stapelgröße und stelle sicher, dass der Gegenstand nicht gesperrt ist, dein Cursor leer ist und du nicht im Kampf bist.")
