T("Choose a style above or change these colors to make a Custom look. Rows update immediately.", "Wähle oben einen Stil oder ändere diese Farben für ein eigenes Erscheinungsbild. Die Zeilen werden sofort aktualisiert.")
T("Choose a style, font and coverage in minutes. Every deeper control remains available in Expert mode.", "Wähle Stil, Schrift und Abdeckung in wenigen Minuten. Alle weiteren Einstellungen bleiben im Expertenmodus verfügbar.")
