T("Choose one font for Blizzard UI text. Existing sizes, outlines, shadows and accessibility scaling are preserved.", "Wähle eine Schrift für Blizzard-UI-Texte. Vorhandene Größen, Umrisse, Schatten und Barrierefreiheits-Skalierung bleiben erhalten.")
T("Choose one material alternative before this slot can enter the total.", "Wähle eine Materialalternative, bevor dieser Platz zur Gesamtsumme zählt.")
T("Choose one target per rule", "Wähle ein Ziel pro Regel")
T("Choose preview DoTs", "Vorschau-DoTs auswählen")
T("Choose supplies from bags", "Vorräte aus Taschen wählen")
T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "Wähle die detaillierte Charakteransicht und ihre Zusatzinformationen. Ein Wechsel der Ansicht lädt die UI neu.")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "Wähle die Dungeon-Schwierigkeitsgrade, in denen MSUF das Kampflog startet. Mythisch+ beginnt mit dem Start des Schlüsselsteins.")
T("Choose the map shape, then adjust its border and outer shadow.", "Wähle die Kartenform und passe dann Rahmen und äußeren Schatten an.")
T("Choose the raid difficulties where MSUF starts the combat log.", "Wähle die Schlachtzugsschwierigkeitsgrade, in denen MSUF das Kampflog startet.")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "Wähle die gemeinsamen Buttonfarben und den Rahmen. Layout, Tastenbelegungen und Sichtbarkeit bleiben wie eingestellt. Änderst du eine einzelne Farbe, wechselt die Bezeichnung auf „Benutzerdefiniert“.")
T("Choose the values shown on each bar.", "Wähle die Werte, die auf jeder Leiste erscheinen.")
T("Choose this character's class and specialization above.", "Wähle oben die Klasse und Spezialisierung dieses Charakters.")
T("Choose this item to add it to your list.", "Wähle diesen Gegenstand, um ihn deiner Liste hinzuzufügen.")
T("Choose volumes for each activity. Turning this off restores the previous volumes when they are still owned by MSUF.", "Lautstärken je Aktivität wählen. Beim Ausschalten werden vorherige Werte wiederhergestellt, sofern MSUF sie noch steuert.")
T("Choose what the Suite tracker lists and when it steps aside.", "Wähle, was der Suite-Tracker auflistet und wann er Platz macht.")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "Wähle, wo die letzten Aktionen erscheinen. Tiefen haben einen eigenen Schalter; Schlachtfelder und Arenen teilen sich einen, und andere Szenarien folgen „Außerhalb von Instanzen“. Wo die Anzeige abgeschaltet ist, hört sie nicht auf deine Zauber.")
T("Choose whether the Time place shows the realm clock or your computer's clock, in 12 or 24 hours, with or without seconds.", "Wähle, ob der Zeitplatz die Realmzeit oder die Uhr deines Computers zeigt: im 12- oder 24-Stunden-Format, mit oder ohne Sekunden.")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "Wähle, welche Blizzard-Fenster den Skin erhalten. Blizzard behält ihre Interaktionen.")
T("Choose which learned portals the minimap flyout and the DataText portal and travel menus list: all of them, those of the current Mythic+ season, which the game keeps up to date each season, or your own set. Learned dungeon portals use secure buttons. Group suggestions require a verified dungeon map or an exact destination match and consider every learned portal. Unknown destinations show no suggestion; buttons hide in combat.", "Wähle, welche gelernten Portale das Minimap-Flyout und die DataText-Menüs für Portale und Reisen anzeigen: alle, die der aktuellen Mythisch+-Saison, die das Spiel jede Saison selbst aktuell hält, oder dein eigenes Set. Erlernte Dungeonportale werden über sichere Schaltflächen gewirkt. Gruppenvorschläge erfordern eine bestätigte Dungeonkarte oder ein exakt übereinstimmendes Ziel und berücksichtigen alle gelernten Portale. Für unbekannte Ziele erscheint kein Vorschlag; im Kampf sind die Schaltflächen ausgeblendet.")
T("Choose your alt, subject and material quantities. Apply and attach from the Send Mail tab, then review and send manually.", "Wähle deinen Zweitcharakter, Betreff und Materialmengen. Übernimm die Daten und Anhänge unter Post senden, prüfe sie und versende manuell.")
T("Choose your buffs or your own harmful auras on the current target. The additional required buff is always checked on you.", "Wähle deine Buffs oder deine eigenen schädlichen Auren auf dem aktuellen Ziel. Der zusätzlich benötigte Buff wird immer auf dir geprüft.")
T("Choose your character", "Eigenen Charakter auswählen")
T("Choose your lure; other consumables are also listed.", "Wähle deinen Angelköder; die Liste enthält auch andere Verbrauchsgegenstände.")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "Die Wahl eines Looks aktualisiert das Skinning und jedes aktivierte Suite-Modul. Später aktivierte Module übernehmen ihn. Neue Skin-Profile beginnen mit %s.")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "Die Bestätigung lässt sich nach deiner Entscheidung zum Überspringen auslassen. Automatisches Überspringen ist eine separate Option und überspringt auch Filme. Beide bleiben im Kampf inaktiv, und eine Fahrzeugsequenz behält immer ihre Bestätigung zum Verlassen. Dieser Helfer kann Tutorials ausblenden, das Löschwort vorausfüllen, die endgültige Bestätigung aber dir überlassen, nur die Erfolgsmeldung für Screenshots ausblenden oder beim Händler dein Charakterfenster auf dem zuletzt genutzten Reiter öffnen. Im Auktionshaus wird Blizzards Filterknopf markiert, solange „Nur aktuelle Erweiterung“ aus ist; setze den Haken dort einmal, und Blizzard behält ihn für diesen Charakter.")
T("Cinematic zone and event announcements in the Suite look.", "Filmreife Gebiets- und Ereignisankündigungen im Suite-Look.")
