T("Copies the spells and items you added to this bar to the same bar in your other specializations. Blizzard's entries follow each specialization's own list. You can undo it.", "Kopiert die Zauber und Gegenstände, die du dieser Leiste hinzugefügt hast, auf dieselbe Leiste in deinen anderen Spezialisierungen. Blizzards Einträge folgen der eigenen Liste jeder Spezialisierung. Du kannst das rückgängig machen.")
