T("Critical strike, haste, mastery and versatility as your character sheet shows them; leech, avoidance and speed can each join the strip (speed is the stat, not your running speed). Show only in combat hides the strip outside fights. Values the game hides show a dash, and the strip updates from your stat events. MSUF Edit Mode moves the strip.", "Kritischer Trefferwert, Tempo, Meisterschaft und Vielseitigkeit wie im Charakterfenster; Lebensraub, Vermeidung und Geschwindigkeit können einzeln dazukommen (Geschwindigkeit ist der Wert, nicht dein Lauftempo). „Nur im Kampf zeigen“ blendet die Leiste außerhalb von Kämpfen aus. Werte, die das Spiel verbirgt, zeigen einen Strich, und die Leiste folgt deinen Wert-Ereignissen. Der MSUF-Bearbeitungsmodus verschiebt die Leiste.")
