T("Dark panel keeps the bank's usual color for the Suite bank views; Match the bag window follows the bag background color and look. The panel stays opaque so Blizzard's own slots never show through it. The size and position apply to the whole bank window, also in Bank tabs. Move the open bank in MSUF Edit Mode, or set the offsets here after turning on the custom position.", "Dunkles Feld behält für die Suite-Bankansichten die übliche Bankfarbe. Wie Taschenfenster übernimmt Hintergrundfarbe und Aussehen des Taschenfensters. Das Feld bleibt undurchsichtig, damit Blizzards Plätze nicht durchscheinen. Größe und Position gelten für das ganze Bankfenster, auch bei Bankreitern. Verschiebe die geöffnete Bank im MSUF-Bearbeitungsmodus oder aktiviere die eigene Position und stelle hier die Versätze ein.")
