T("Drop an item onto Pinned items in the category sidebar to keep it at the top of every view. Recent items lists up to 200 item types this character received, also across logins; each leaves the list once it is older than the hours set here, and Clear recent items empties it sooner. Neither action moves or deletes an item.", "Ziehe einen Gegenstand auf Angeheftete Gegenstände in der Kategorien-Seitenleiste, um ihn in jeder Ansicht oben zu behalten. Letzte Gegenstände listet bis zu 200 Gegenstandstypen, die dieser Charakter erhalten hat, auch über Anmeldungen hinweg; jeder verlässt die Liste, sobald er älter als die hier eingestellten Stunden ist, und Letzte Gegenstände leeren leert sie früher. Keine dieser Aktionen verschiebt oder löscht Gegenstände.")
T("Dropdown and previous/next arrows", "Dropdown- und Zurück-/Weiter-Pfeile")
T("Drops this bar's own order and the spells and items you added to it, for this specialization. Spells you removed stay hidden: Show removed spells brings them back. You can undo it.", "Verwirft für diese Spezialisierung die eigene Reihenfolge dieser Leiste sowie die Zauber und Gegenstände, die du hinzugefügt hast. Entfernte Zauber bleiben verborgen: „Entfernte Zauber anzeigen“ holt sie zurück. Du kannst das rückgängig machen.")
