T("Each phrase may contain up to 80 characters.", "Jeder Suchbegriff darf höchstens 80 Zeichen enthalten.")
T("Each response is its own switch and none acts in combat. A summon that skips a starting area, and a resurrection during a boss encounter or while Blizzard makes you wait, stay yours. Party invite declines never touch friends, Battle.net friends or guild members, and invites that ask for a role or start a quest session stay yours. A chat line can report each response.", "Jede Antwort hat einen eigenen Schalter und wird nie im Kampf ausgeführt. Bei Beschwörungen, die ein Startgebiet überspringen, sowie Wiederbelebungen während eines Bosskampfes oder einer Blizzard-Wartezeit entscheidest du selbst. Das Ablehnen von Gruppeneinladungen betrifft nie Freunde, Battle.net-Freunde oder Gildenmitglieder. Einladungen mit Rollenabfrage und zu Questsitzungen beantwortest du selbst. Jede Antwort kann im Chat gemeldet werden.")
T("Each specialization keeps its own bar layout: positions, attachments, growth, rows, spacing and sizes. Until it has its own, it uses the current one.", "Jede Spezialisierung behält ihr eigenes Leistenlayout: Positionen, Anheftungen, Wachstum, Reihen, Abstände und Größen. Solange sie noch keines hat, nutzt sie das aktuelle.")
T("Each window keeps its own meter, fight, size and visibility rules. Drag the header or use MSUF Edit Mode to move it.", "Jedes Fenster hat eigene Anzeige, eigenen Kampf, eigene Größe und Sichtbarkeitsregeln. Ziehe es an der Kopfzeile oder verschiebe es im MSUF-Bearbeitungsmodus.")
