T("Enter a spell name or ID on MSUF action bars. Its buttons glow from the aura and unit selected below. A page change in combat pauses the glow until combat ends.", "Gib einen Zaubernamen oder eine ID auf MSUF-Aktionsleisten ein. Seine Buttons leuchten anhand der unten ausgewählten Aura und Einheit. Ein Seitenwechsel im Kampf pausiert den Glow bis zum Kampfende.")
T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "Gib einen Talent- oder Zaubernamen oder eine ID ein und drücke Enter. Jeder erforderliche Zauber muss erlernt sein. Ein leeres Feld entfernt diese Bedingung.")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "Gib einen Talent- oder Zaubernamen oder eine ID ein und drücke Enter. Der Eintrag wird ausgeblendet, sobald einer der ausgeschlossenen Zauber erlernt ist. Bedingungen werden außerhalb des Kampfes aktualisiert.")
