T("Enter the cast spell's name or ID. Leave empty for automatic spell matching. Timers start only from readable player cast events.", "Gib den Namen oder die ID des gewirkten Zaubers ein. Leer lassen für automatische Zauberzuordnung. Timer starten nur bei lesbaren Zauberereignissen des Spielers.")
T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "Gib bis zu 200 Gegenstands-IDs ein. Ein Knopf erscheint nur bei einem Händler und zeigt verkäufliche Stapel als Vorschau an; ein Klick öffnet die Bestätigung. Vor dem Verkauf prüft der Helfer Gegenstand, Qualität, Wert, Queststatus und Taschenplatz erneut. Anlegbare Gegenstände benötigen eine separate Freigabe.")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "Gib bis zu acht Zauber-IDs für Bewegungsfähigkeiten ein. Wenn du dich in Bewegung setzt, wird der erste bekannte, bereite und nutzbare Zauber kurz angezeigt. Eine gemeinsame Abklingzeit von 20 Sekunden begrenzt die Hinweise. Ohne IDs passiert nichts. Verschiebe den Hinweis im MSUF-Bearbeitungsmodus.")
