T("Equipment choices (the list that opens from a gear slot) show the item level on each item, so you can compare without hovering. The arrows beside the gear slots can be hidden; hold Alt over a slot to open its choices.", "Die Ausrüstungsauswahl (die Liste, die sich an einem Ausrüstungsplatz öffnet) zeigt die Gegenstandsstufe jedes Gegenstands, damit du ohne Überfahren vergleichen kannst. Die Pfeile neben den Ausrüstungsplätzen lassen sich ausblenden; halte Alt über einem Platz, um seine Auswahl zu öffnen.")
T("Equipment item levels appear in the upper right of each slot. Choose a font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Missing item data appears when the client provides it.", "Gegenstandsstufen der Ausrüstung erscheinen oben rechts in jedem Platz. Wähle Schriftart, Kontur, Schatten und die Darstellung Weich, Scharf oder Slug. Slug hat keinen Schatten. Fehlende Gegenstandsdaten erscheinen, sobald der Client sie liefert.")
