T("Font, text sizes and background opacity. The tracker colors are in this section's three-dot menu; picking one switches the color source to Custom colors.", "Schriftart, Textgrößen und Hintergrunddeckkraft. Die Trackerfarben liegen im Drei-Punkte-Menü dieses Abschnitts; die Wahl einer Farbe stellt die Farbquelle auf eigene Farben um.")
T("Fonts", "Schriftarten")
T("Fonts, outlines, shadows and Smooth/Sharp/Slug rendering for keybinds, macro names, counts and cooldown numbers. Sizes are set per bar below. Slug has no shadow.", "Schriftarten, Konturen, Schatten und die Darstellung Weich/Scharf/Slug für Tastenbelegungen, Makronamen, Anzahlen und Abklingzeitzahlen. Größen werden unten pro Leiste festgelegt. Slug hat keinen Schatten.")
