T("For Warlocks: show Burning Rush only while its aura is active in combat. Blizzard's native aura container follows the aura; Suite does not scan auras. MSUF Edit Mode shows a sample and moves the cue.", "Für Hexenmeister: Zeigt Brennender Ansturm nur im Kampf an, solange die Aura aktiv ist. Blizzards nativer Auracontainer verfolgt die Aura; Suite durchsucht Auren nicht selbst. Im MSUF Edit Mode kannst du eine Vorschau sehen und den Hinweis verschieben.")
T("Forces", "Streitkräfte")
T("Forever Suite layout with Antique Map and optional parchment Skin.", "Forever-Suite-Layout mit Antique Map und optionalem Pergament-Skin.")
T("Forever artwork", "Forever-Design")
T("Forever factory profile unavailable", "Forever-Werksprofil nicht verfügbar")
T("Forever only. A secure fishing key that casts Fishing, equipping the rod you choose first, and a second key that applies the lure you choose. Set both under Keybindings > MSUF Suite. Each action needs your key press; interacting with the bobber stays manual. The optional sound profile sets your fishing volumes while you cast and restores them afterwards.", "Nur Forever. Eine sichere Angeltaste legt zuerst die gewählte Angel an und wirkt dann Angeln. Eine zweite Taste bringt den gewählten Köder an. Belege beide unter Tastenbelegung > MSUF Suite. Jede Aktion erfordert deinen Tastendruck; den Schwimmer bedienst du manuell. Das optionale Soundprofil setzt beim Auswerfen deine Angellautstärken und stellt sie danach wieder her.")
T("Forever only. Route times are learned from completed flight-master journeys and kept in this profile. A first journey has no invented estimate. Early landing does not overwrite a full-route time. Intermediate stops come from the native taxi map; its tooltip can preview the route. Land at next stop requests the next available landing point.", "Nur Forever. Zeiten vollständiger Flugmeisterreisen werden gelernt und in diesem Profil gespeichert. Für die erste Reise wird keine Zeit erfunden. Frühes Landen überschreibt keine vollständige Routenzeit. Zwischenhalte stammen aus der nativen Flugkarte; ihr Tooltip zeigt die Routenvorschau. „Am nächsten Halt landen“ fordert den nächsten verfügbaren Landeplatz an.")
T("Forever only. When a quest offers a choice of rewards, the one with the highest vendor value, counting its stack size, is marked. Nothing is selected or turned in for you.", "Nur Forever. Bietet eine Quest mehrere Belohnungen, wird die mit dem höchsten Händlerwert unter Berücksichtigung der Stapelgröße markiert. Es wird nichts für dich ausgewählt oder abgegeben.")
