T("Forget everything recorded for %s? While Inventory archive is on, it is recorded again the next time your bags change.", "Alle Aufzeichnungen für %s vergessen? Mit aktiviertem Inventararchiv werden sie bei der nächsten Änderung deiner Taschen erneut erfasst.")
