T("Frames join aligned bars; detached bars keep separate frames. Effects are static. Threshold marks a fixed percentage. Preview switches apply live.", "Der Außenrahmen verbindet Gesundheits- und Zauberbalken und umschließt ohne sichtbaren Zauber nur den Gesundheitsbalken. Schatten und Leuchten sind statisch. Die Balkenstruktur erhält Gesundheits- und Aurafarben. Die Schwellenlinie markiert einen festen Prozentwert und ist keine Hinrichten-Warnung. Über Vorschau-Ebenen lässt sich jede Funktion ein- oder ausschalten. Versetzte oder unterschiedlich breite Balken behalten getrennte Rahmen.")
