T("Gives Blizzard's player buffs and debuffs the icon skins you chose on the Icon Skins page, at Blizzard's own size and layout. The skins are painted once, out of combat, and no code runs on aura updates. While Player aura layout is on, it paints the buttons itself and this switch waits.", "Gestaltet Blizzards Spieler-Buffs und -Debuffs mit den auf der Seite Symbol-Skins gewählten Skins, bei Blizzards Größe und Anordnung. Die Skins werden einmal außerhalb des Kampfes aufgetragen; bei Aura-Updates läuft kein Code. Solange Spieler-Aura-Anordnung aktiv ist, gestaltet sie die Schaltflächen selbst und dieser Schalter wartet.")
T("Gives this bar's place, attachment, growth, rows and sizes to your other specializations. You can undo it.", "Übernimmt Position, Anker, Wachstumsrichtung, Reihen und Größen dieser Leiste für andere Spezialisierungen. Du kannst dies rückgängig machen.")
