T("How the icons line up and grow. A free bar's position counts from the screen center; an attached bar's is an offset from its attach point. Excess cooldowns can move past Maximum icons to another enabled cooldown bar. The destination must have overflow off; chained routes are ignored.", "Anordnung und Wachstum der Symbole. Die Position einer freien Leiste wird von der Bildschirmmitte aus gemessen, die einer angehängten Leiste vom Ankerpunkt. Überzählige Abklingzeiten können nach der maximalen Symbolzahl an eine andere aktive Abklingzeitleiste weitergeleitet werden. Das Ziel muss die Weiterleitung deaktiviert haben; verkettete Weiterleitungen werden ignoriert.")
