T("Item tooltips take the color of the item quality, unit tooltips the class color of a player or the reaction color of any other unit. Keep leaves the border as it is. The Suite skin's tooltip border takes the color too.", "Gegenstands-Tooltips übernehmen die Qualitätsfarbe, Einheiten-Tooltips die Klassenfarbe eines Spielers oder die Reaktionsfarbe anderer Einheiten. Beibehalten lässt den Rand unverändert. Auch der Tooltip-Rand des Suite-Skins übernimmt die Farbe.")
