T("Items you protect are skipped by every sale action of the Suite. With the equipment set switch on, all equippable items are protected while any equipment set exists, because exact set membership is not available to this helper. Manage the protected items in the inventory tool.", "Geschützte Gegenstände werden bei allen Verkaufsaktionen der Suite übersprungen. Ist der Ausrüstungsset-Schutz aktiv, sind bei vorhandenen Ausrüstungssets alle anlegbaren Gegenstände geschützt, da dieser Helfer die genaue Setzugehörigkeit nicht ermitteln kann. Verwalte die geschützten Gegenstände im Inventarwerkzeug.")
