T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Sort items by orders every Suite view; Name keeps the order each view has always had. Click a category header to hide or show its items. The footer counts free slots, and Mark items that beat what you wear puts a small arrow on equipment that beats what you wear in its slot. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "Behalte Blizzards Raster oder wähle ein Suite-Raster, physische Taschengruppen oder Kategorien. Unter Kategorien bearbeiten im Taschenfenster kannst du Kategorien erstellen, umbenennen, umsortieren und deaktivieren. Ziehe Gegenstände auf eine Kategorie in der Seitenleiste, um sie zuzuweisen. Gegenstände sortieren nach ordnet jede Suite-Ansicht; Name behält die bisherige Reihenfolge bei. Ein Klick auf einen Kategorienamen blendet dessen Gegenstände aus oder ein. Die Fußzeile zählt freie Plätze. Bessere Ausrüstung markieren zeigt einen kleinen Pfeil an Gegenständen, die für ihren Platz besser als deine angelegte Ausrüstung sind. Bei großen Inventaren kannst du scrollen oder Zurück und Weiter nutzen; im Kampf erscheinen alle Plätze gleichzeitig. Zusammengefasste Stapelzahlen sind nur optisch. An Bank, Gildenbank, Post, Handel, Auktionshaus und Händler werden immer die physischen Stapel wiederhergestellt.")
