T("Lightweight meter windows for damage, healing, interrupts, dispels, deaths and damage taken. They read the client's own combat data; Blizzard's meter window stays hidden while this module is active.", "Schlanke Fenster für Schaden, Heilung, Unterbrechungen, Bannungen, Tode und erlittenen Schaden. Sie lesen die eigenen Kampfdaten des Clients; Blizzards Schadensanzeige bleibt ausgeblendet, solange dieses Modul aktiv ist.")
