T("MSUF icons replace the scattered Blizzard chat controls. Friends, channels, text to speech and the chat menu keep their Blizzard actions; the bottom icon jumps to the newest message. Turn this off to restore the native buttons.", "MSUF-Symbole ersetzen Blizzards verstreute Chat-Steuerelemente. Freunde, Kanäle, Text-zu-Sprache und das Chatmenü behalten ihre Blizzard-Aktionen; das untere Symbol springt zur neuesten Nachricht. Schalte dies aus, um die ursprünglichen Buttons wiederherzustellen.")
