T("MSUF stops only a log it started. A log that was already on stays on. Re-entering selected content cancels a pending stop. WoW writes the log in its Logs folder.", "MSUF beendet nur ein Log, das es selbst gestartet hat. Ein bereits laufendes Log bleibt an. Erneutes Betreten gewählter Inhalte bricht ein ausstehendes Beenden ab. WoW schreibt das Log in seinen Ordner „Logs“.")
