T("Observed enemies adds up the enemy forces of the living enemies in combat that you see as a nameplate or target, and the total they would bring. Enemies that give no forces count as zero; while the client keeps a value hidden, the line shows -- instead of a guess. Enemies out of sight are not counted.", "Beobachtete Gegner addiert die Streitkräfte der lebenden Gegner im Kampf, die du als Namensplakette oder Ziel siehst, und zeigt die Summe, die sie bringen würden. Gegner ohne Streitkräfte zählen als null; solange der Client einen Wert verbirgt, zeigt die Zeile -- statt einer Schätzung. Gegner außer Sicht werden nicht gezählt.")
