T("Only containers newly acquired after enabling this helper are opened. It waits for combat to end, opens one at a time, and leaves them to you while you hold Shift or a loot window or a window that gives item use another meaning is open: merchant, bank, guild bank, mail, trade, auction house, scrapper, socket, upgrade and similar. Warbound containers stay unopened unless you allow them; profiles that used this helper before keep opening them. Midnight Artisan payouts can wait while your Shard of Dundun is capped.", "Nur Behälter, die nach dem Aktivieren dieses Helfers neu hinzukommen, werden geöffnet. Er wartet bis nach dem Kampf, öffnet sie einzeln und überlässt sie dir, solange du Umschalt gedrückt hältst oder ein Beutefenster oder ein Fenster offen ist, das dem Benutzen eines Gegenstands eine andere Bedeutung gibt: Händler, Bank, Gildenbank, Post, Handel, Auktionshaus, Verwerter, Sockel, Aufwertung und Ähnliches. Kriegsmeuten-Container bleiben ungeöffnet, solange du sie nicht zulässt; Profile, die diesen Helfer schon vorher nutzten, öffnen sie weiterhin. Midnight-Handwerksauszahlungen können warten, solange dein Splitter von Dundun am Limit ist.")
T("Only in an active Delve and outside combat: if the player choice has exactly one enabled spell option, one button and no confirmation, MSUF selects it once. Other choices remain manual.", "Nur in einer aktiven Tiefe und außerhalb des Kampfes: Wenn eine Auswahl genau eine verfügbare Zauberoption, einen Knopf und keine Bestätigung hat, wählt MSUF sie einmalig aus. Andere Entscheidungen bleiben manuell.")
T("Only inside instances", "Nur in Instanzen")
