T("Pick the places where reminders may show; arenas and battlegrounds never show them. Before a keystone starts, buffs can be asked to last the dungeon's timer or a number of minutes; once the key starts, the normal warning time applies again. One scheduled wakeup handles the next expiry.", "Wähle die Orte, an denen Erinnerungen erscheinen dürfen; in Arenen und Schlachtfeldern erscheinen sie nie. Bevor ein Schlüsselstein startet, können Buffs so lange halten müssen wie der Timer des Dungeons oder eine Anzahl Minuten; sobald der Schlüssel läuft, gilt wieder die normale Warnzeit. Ein geplanter Weckruf übernimmt den nächsten Ablauf.")
