T("Remembers your characters that you visit while this helper is on and lists them beside the mail window. Click a name to fill the recipient, right-click to hide or restore it, and search by name. Only characters on your current or connected realms are listed. Sending stays manual.", "Merkt sich die Charaktere, mit denen du dich bei aktiviertem Helfer einloggst, und listet sie neben dem Postfenster auf. Klicke einen Namen an, um den Empfänger einzutragen. Rechtsklicken blendet ihn aus oder wieder ein; gesucht wird nach Namen. Es werden nur Charaktere auf deinem aktuellen oder verbundenen Realms angezeigt. Das Absenden bleibt manuell.")
