T("Reminders appear only outside combat. The advance setting also shows active buffs, food and weapon enchants when their remaining time reaches the chosen number of minutes; 0 shows only missing effects. A single scheduled wakeup handles the next threshold. Reminders hide in arenas and battlegrounds, where aura data can be restricted.", "Erinnerungen erscheinen nur außerhalb des Kampfes. Die Vorlaufeinstellung zeigt auch aktive Buffs, Essen und Waffenverzauberungen, wenn ihre Restzeit die gewählte Minutenzahl erreicht; 0 zeigt nur fehlende Effekte. Ein einziger geplanter Weckruf übernimmt die nächste Schwelle. Erinnerungen werden in Arenen und Schlachtfeldern ausgeblendet, wo Aurendaten eingeschränkt sein können.")
T("Reminders for missing poisons and consumables.", "Erinnerungen an fehlende Gifte und Verbrauchsgüter.")
T("Reminders for the buffs your class and specialization keep up.", "Erinnerungen für Buffs, die deine Klasse und Spezialisierung aufrechterhalten.")
