T("Sets music, ambience and effects volumes for the activity you are in. Volumes change out of combat only, and MSUF restores the ones it set when you turn this off, unless you changed them yourself meanwhile. Turn this off to keep your own volumes and only mute sound files below.", "Stellt Musik-, Umgebungs- und Effektlautstärke für deine aktuelle Aktivität ein. Änderungen erfolgen nur außerhalb des Kampfes. Beim Deaktivieren stellt MSUF seine Änderungen wieder zurück, sofern du die Lautstärke inzwischen nicht selbst geändert hast. Schalte dies aus, um deine eigenen Lautstärken zu behalten und nur die unten angegebenen Sounddateien stummzuschalten.")
