T("Shown windows: %d. Raise the number of windows to show this one.", "Angezeigte Fenster: %d. Erhöhe die Anzahl der Fenster, um dieses anzuzeigen.")
T("Shows Blizzard's shared battle resurrection charges in an active Mythic+ run or raid encounter. The icon counts down to the next charge using Blizzard's cooldown display. Hidden when the shared pool is unavailable. MSUF Edit Mode previews the display and edits X, Y, width, height and scale.", "Zeigt Blizzards gemeinsame Aufladungen der Kampfwiederbelebung in einem aktiven Mythisch+-Durchlauf oder einer Schlachtzugsbegegnung. Das Symbol zählt mit Blizzards Abklingzeitanzeige bis zur nächsten Aufladung herunter. Ausgeblendet, wenn der gemeinsame Pool nicht verfügbar ist. Der MSUF-Bearbeitungsmodus zeigt eine Vorschau der Anzeige und bearbeitet X, Y, Breite, Höhe und Skalierung.")
T("Shows an approximate range to your current target from the game's range checks of spells you know; values include the target's hitbox, and dashes mean that no known spell can tell. Write the text with {range} and {unit}. The estimate can sit below the target frame, following it when the frame moves, or anywhere on screen; MSUF Edit Mode moves both placements.", "Zeigt eine ungefähre Entfernung zu deinem aktuellen Ziel anhand der Reichweitenprüfungen des Spiels für Zauber, die du kennst; die Werte schließen die Trefferzone des Ziels ein, und Striche bedeuten, dass kein bekannter Zauber es bestimmen kann. Formuliere den Text mit {range} und {unit}. Die Schätzung kann unter dem Zielrahmen sitzen, und ihm folgen, wenn sich der Rahmen bewegt, oder frei auf dem Bildschirm; der MSUF-Bearbeitungsmodus verschiebt beide Platzierungen.")
T("Shows each ready interrupt with the bar's glow style while the target's cast can be interrupted. Requires per-interrupt readiness from MSUF.", "Zeigt jede bereite Unterbrechung mit dem Leuchtstil der Leiste an, solange der Zauber des Ziels unterbrochen werden kann. Benötigt Bereitschaftsdaten für einzelne Unterbrechungen von MSUF.")
T("Shows incoming damage and healing for you or your vehicle. Blizzard's own combat text is hidden while enabled and restored when disabled. Move the display in MSUF Edit Mode. During heavy bursts the oldest of the visible messages is replaced. The game may keep amounts private, so messages are never combined or filtered by their value.", "Zeigt eingehenden Schaden und Heilung für dich oder dein Fahrzeug. Blizzards eigener Kampftext wird währenddessen ausgeblendet und beim Deaktivieren wiederhergestellt. Verschiebe die Anzeige im MSUF-Bearbeitungsmodus. Bei vielen Meldungen wird die älteste sichtbare ersetzt. Das Spiel kann Zahlen geheim halten; Meldungen werden deshalb weder addiert noch nach ihrem Wert gefiltert.")
T("Shows item levels on merchant equipment when Blizzard has loaded its item data. Buyback items and items without an item level stay unchanged.", "Zeigt Gegenstandsstufen auf Händlerausrüstung, sobald Blizzard die Gegenstandsdaten geladen hat. Rückkaufgegenstände und Gegenstände ohne Gegenstandsstufe bleiben unverändert.")
T("Shows the active potion buff. Instant healing and mana potions do not leave a buff.", "Zeigt den aktiven Trank-Buff. Sofort wirkende Heil- und Manatränke hinterlassen keinen Buff.")
T("Shows the current loot specialization when you open the Great Vault. Updates if you change loot specialization while the window is open.", "Zeigt die aktuelle Beutespezialisierung, wenn du die Große Schatzkammer öffnest. Aktualisiert sich, wenn du die Beutespezialisierung bei geöffnetem Fenster änderst.")
T("Shows the lowest equipped durability below your chosen threshold, outside combat. MSUF Edit Mode shows a sample even when your gear is repaired. Its popup edits X, Y, width, height and scale.", "Zeigt außerhalb des Kampfes die niedrigste Haltbarkeit angelegter Ausrüstung unter deiner gewählten Grenze. Der MSUF-Bearbeitungsmodus zeigt ein Beispiel, auch wenn deine Ausrüstung repariert ist. Sein Popup bearbeitet X, Y, Breite, Höhe und Skalierung.")
T("Shows the number you own, including your bank and Warband bank, when the item tooltip has a public item ID. Optionally separate storage locations. Empty counts are omitted.", "Zeigt deine Gegenstandsanzahl einschließlich Bank und Kriegsmeutenbank an, wenn die Gegenstands-ID öffentlich ist. Lagerorte können getrennt angezeigt werden. Leere Lagerorte entfallen.")
T("Shows the share of the keystone's enemy forces that an enemy gives, while a Mythic+ keystone is running and Blizzard shows no such line itself.", "Zeigt während eines Mythisch+-Schlüsselsteins den Streitkräfteanteil eines Feindes an, falls Blizzard selbst keine solche Zeile anzeigt.")
T("Shows the spell's icon in the middle of the screen when its cooldown ends, even while this bar is hidden. Its size, place and time are in General.", "Zeigt das Zaubersymbol nach Ende seiner Abklingzeit in der Bildschirmmitte an, auch wenn diese Leiste ausgeblendet ist. Größe, Position und Dauer stehen unter Allgemein.")
T("Shows the total durability of your gear on the character model, moved by the two offsets, and crops the edges of the gear slot icons on your character sheet and in the Inspect window.", "Zeigt die Gesamthaltbarkeit deiner Ausrüstung auf dem Charaktermodell, verschoben um die beiden Versätze, und schneidet die Ränder der Platzsymbole in deinem Charakterfenster und im Betrachtenfenster zu.")
T("Shows up to three extra compact notices for Blizzard personal item-loot toasts. Filter by minimum quality, mount or pet items, and optionally up to 100 item IDs. Native Blizzard notices remain visible; ordinary bag additions without a toast are not included.", "Zeigt bis zu drei zusätzliche kompakte Hinweise für Blizzards persönliche Gegenstandsbeute an. Filtere nach Mindestqualität, Reittieren oder Haustieren und optional nach bis zu 100 Gegenstands-IDs. Blizzards ursprüngliche Hinweise bleiben sichtbar; normale Taschenzugänge ohne Beutehinweis sind nicht enthalten.")
T("Shows whichever haste buff is active, from any source: Bloodlust, Heroism, Time Warp, Primal Rage, Fury of the Aspects and similar.", "Zeigt den aktiven Tempobuff unabhängig von seiner Quelle an: Kampfrausch, Heldentum, Zeitkrümmung, Urtümliche Wut, Zorn der Aspekte und ähnliche Effekte.")
T("Shows your current talent build and loot specialization on ready checks, when a dungeon queue pops, or when you enter an instance. It never changes your talents or loot spec.", "Zeigt deine aktuelle Talentvorlage und Beutespezialisierung bei Bereitschaftsabfragen, beim Aufpoppen der Dungeonsuche oder beim Betreten einer Instanz. Talente und Beutespezialisierung werden nie automatisch geändert.")
T("Shows your most recent successful spells. Standard rows have an icon, name and marker; Icons only is a compact vertical icon column. Display width applies to standard rows; icon width follows row height in the icon preset. Position and anchor are set in MSUF Edit Mode, which shows sample actions. The list stops listening while disabled. Spells whose details the client keeps private cannot appear.", "Zeigt deine zuletzt erfolgreich gewirkten Zauber. Standardzeilen enthalten Symbol, Namen und Markierung; „Nur Symbole“ ist eine kompakte senkrechte Symbolspalte. Die Anzeigebreite gilt für Standardzeilen, während die Symbolbreite in der Symbolvorlage von der Zeilenhöhe abhängt. Position und Anker stellst du im MSUF-Edit-Mode ein; dort werden Beispielaktionen angezeigt. Ist die Liste deaktiviert, verarbeitet sie keine Ereignisse. Zauber, deren Details der Client geheim hält, können nicht erscheinen.")
T("Shows your own Bloodlust exhaustion while in a group, or a ready state if you prefer. Relevant player aura changes update it; MSUF Edit Mode moves it and previews the locked state.", "Zeigt in einer Gruppe deine eigene Kampfrausch-Erschöpfung oder auf Wunsch den Bereitschaftsstatus. Relevante Änderungen deiner Auren aktualisieren die Anzeige; im MSUF-Edit-Mode kannst du sie verschieben und den gesperrten Zustand als Vorschau sehen.")
