T("Silences the game sound files whose IDs you list, such as a mount or summon sound; up to 200. MSUF mutes exactly the files listed here and plays them again when you remove an ID or turn this helper off, and it leaves files muted by other addons alone. Muting works whether or not volume profiles are applied.", "Schaltet die Spiel-Sounddateien mit den eingetragenen IDs stumm, etwa Reittier- oder Beschwörungstöne; bis zu 200. MSUF schaltet nur diese Dateien stumm und gibt sie wieder frei, wenn du eine ID entfernst oder den Helfer deaktivierst. Von anderen Addons stummgeschaltete Dateien bleiben unverändert. Das funktioniert auch ohne aktive Lautstärkeprofile.")
T("Silences these game sound files, such as a mount or summon sound, while this helper is on. Remove an ID to hear that sound again.", "Schaltet diese Spiel-Sounddateien, etwa Reittier- oder Beschwörungstöne, stumm, solange der Helfer aktiv ist. Entferne eine ID, um den Ton wieder zu hören.")
