T("Sort applicants for your own Mythic+ listing by their average member score, highest first. Ties keep Blizzard's order. If any score is missing or restricted, the native order remains. The closed list is untouched.", "Sortiert Bewerber für eure eigene Mythic+-Gruppe nach der durchschnittlichen Wertung ihrer Mitglieder, höchste zuerst. Bei Gleichstand bleibt Blizzards Reihenfolge erhalten. Fehlt eine Wertung oder ist sie geschützt, bleibt die normale Reihenfolge erhalten. Bei geschlossenem Fenster wird nichts geändert.")
