T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. The bank views have the same smart search, free slot count and collapsible category headers. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "Wechsle über die Schaltfläche unter dem Bankfenster zwischen nativen Reitern, kombinierter Bank, kombinierter Kriegsmeutenbank und gemeinsamen Kategorien. Gemeinsame Kategorien enthalten zugängliche Charakter- und Kriegsmeutenbankfächer. Bankfächer verwalten führt zurück zu Blizzards Kauf-, Einzahlungs- und Fachoptionen. Die Bankansichten bieten dieselbe intelligente Suche, freie-Plätze-Anzeige und einklappbare Kategorieüberschriften. Jeder Platz behält seine eigene Gegenstandsaktion und Bankstapel werden nie zusammengelegt. Ein Klick auf einen Kriegsmeutengegenstand wählt zuerst Blizzards Kriegsmeutenbank-Reiter. Erstattbare Gegenstände erfordern vor dem Einlagern in die Kriegsmeutenbank eine Bestätigung.")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Select Layout to customize the bar selected above.", "Schalte hier einzelne Leisten ein oder aus. Beim Einschalten wird ihre vorherige Sichtbarkeitsregel wiederhergestellt. Unter Layout kannst du die oben ausgewählte Leiste anpassen.")
T("Switch on the first option, then keep or drop the reminders you want. A reminder shows only when your character knows its spell. Stances, auras, shields, Shadowform and weapon or shield imbues show while they are missing. Buffs you put on an ally (Source of Magic, Blistering Scales, Earth Shield, Symbiotic Relationship) show while your buff is on nobody in the group; target an ally and click the icon to cast it. Right-click or middle-click any reminder to hide it until you reload the UI.", "Schalte die erste Option ein und behalte dann die gewünschten Erinnerungen oder schalte andere aus. Eine Erinnerung erscheint nur, wenn dein Charakter den Zauber kennt. Haltungen, Auren, Schilde, Schattengestalt sowie Waffen- und Schildverstärkungen werden angezeigt, solange sie fehlen. Stärkungszauber für Verbündete (Quelle der Magie, Sengende Schuppen, Erdschild, Symbiotische Beziehung) erscheinen, solange niemand in der Gruppe deinen Stärkungszauber hat. Nimm einen Verbündeten ins Ziel und klicke zum Wirken auf das Symbol. Rechts- oder Mittelklicken blendet eine Erinnerung bis zum nächsten Neuladen der Benutzeroberfläche aus.")
