T("Textures use the window and header colors and opacity. Turn the texture switch off to return to a flat color.", "Texturen nutzen Farbe und Deckkraft von Fenster und Kopfzeile. Schalte die Textur aus, um wieder eine einfarbige Fläche zu verwenden.")
