T("These apply to every bar. The standalone assisted icon follows Blizzard's assisted combat highlight; enable that highlight in the game's Combat options. Its position is available in MSUF Edit Mode. Action bar presses show on cooldown icons only with the MSUF Suite action bars.", "Diese Einstellungen gelten für alle Leisten. Das eigenständige Unterstützungssymbol folgt Blizzards Hervorhebung der Kampfunterstützung; aktiviere sie in den Kampfoptionen des Spiels. Die Position lässt sich im MSUF-Bearbeitungsmodus ändern. Tastendrücke auf Aktionsleisten werden nur mit den MSUF-Suite-Aktionsleisten auf Abklingzeitsymbolen angezeigt.")
T("These apply to every bar:", "Diese gelten für jede Leiste:")
T("These are dated snapshots. Visit each character and open their bank to refresh its recorded contents.", "Dies sind datierte Aufzeichnungen. Besuche jeden Charakter und öffne seine Bank, um die gespeicherten Inhalte zu aktualisieren.")
