T("These spells apply to all specializations. Clearing the group empties it for all of them; turning sharing off brings back each spec's own list.", "Diese Zauber gelten für alle Spezialisierungen. Das Leeren der Gruppe leert sie für alle; wenn du das Teilen ausschaltest, kehrt die eigene Liste jeder Spezialisierung zurück.")
