T("Used when a clock, FPS or latency text shows instance lockouts or the Great Vault on mouseover.", "Gilt, wenn Uhr-, FPS- oder Latenztext bei Mouseover Instanzsperren oder die Große Schatzkammer zeigen.")
T("Uses Blizzard's Sell All Junk action when a merchant opens, including its per-bag exclusions. Hold Shift while opening the merchant to skip selling. The optional chat line confirms the request, not completed sales.", "Nutzt beim Öffnen eines Händlers Blizzards Aktion „Plunder verkaufen“, einschließlich ihrer Ausschlüsse pro Tasche. Halte beim Öffnen des Händlers die Umschalttaste, um den Verkauf zu überspringen. Die optionale Chatzeile bestätigt die Anfrage, nicht abgeschlossene Verkäufe.")
T("Uses MSUF's default spell lists for each specialization. Your own list changes are kept. This does not switch Suite profiles.", "Verwendet die Standard-Zauberlisten von MSUF für jede Spezialisierung. Deine eigenen Listenänderungen bleiben erhalten. Das wechselt keine Suite-Profile.")
T("Uses the inspect result that supplies the item level, so it sends no request of its own. Your own specialization needs none.", "Nutzt das Abfrageergebnis, das bereits die Gegenstandsstufe liefert, und sendet keine eigene Anfrage. Für deine eigene Spezialisierung ist keine Anfrage nötig.")
