T("Warn when your pet is missing or dead. By default, the missing warning applies to Hunters and Warlocks; the dead warning applies to any class with a pet. MSUF Edit Mode moves the alert.", "Warnt, wenn dein Begleiter fehlt oder tot ist. Standardmäßig gilt die Warnung bei fehlendem Begleiter für Jäger und Hexenmeister; vor einem toten Begleiter wird bei jeder Klasse mit Begleiter gewarnt. Im MSUF-Edit-Mode kannst du die Anzeige verschieben.")
