T("Welcome to MSUF Suite", "Willkommen bei MSUF Suite")
T("What to remind", "Woran erinnern")
T("What to track", "Was verfolgen")
T("When BigWigs, Details or another addon provides LibKeystone or LibOpenRaid, a keys request asks it too, so players without the Suite are listed.", "Wenn BigWigs, Details oder ein anderes Addon LibKeystone oder LibOpenRaid bereitstellt, fragt eine Schlüsselanfrage dort ebenfalls nach. So erscheinen auch Spieler ohne Suite.")
T("When a dungeon queue pops", "Wenn die Dungeonsuche eine Gruppe findet")
T("When a ready check starts outside combat and your mana as a healer is low, a short note shows how much you have; it turns red below half of your limit. Only your own mana is read.", "Wenn außerhalb des Kampfes ein Bereitschaftscheck startet und dein Mana als Heiler niedrig ist, zeigt ein kurzer Hinweis, wie viel du hast; unter der Hälfte deiner Grenze wird er rot. Gelesen wird nur dein eigenes Mana.")
T("When equipment sets exist, all equippable items are protected. Exact set membership is unavailable to this helper.", "Wenn Ausrüstungssets existieren, werden alle anlegbaren Gegenstände geschützt. Die genaue Setzugehörigkeit steht diesem Helfer nicht zur Verfügung.")
T("When leaving", "Beim Verlassen")
T("When someone offers you a resurrection, its dialog gets a green frame, optionally with Blizzard's ready check sound, and its accept button can get a green frame of its own. Accepting stays your click.", "Bietet dir jemand eine Wiederbelebung an, bekommt der Dialog einen grünen Rahmen, auf Wunsch mit Blizzards Bereitschaftscheck-Ton, und sein Annehmen-Knopf kann einen eigenen grünen Rahmen bekommen. Das Annehmen bleibt dein Klick.")
T("When the key ends", "Wenn der Schlüssel endet")
T("When the native group listing panel closes with applications still active, show their count in your own chat. Your applications remain active and no group chat is sent.", "Wenn du die native Gruppensuche mit noch aktiven Bewerbungen schließt, wird ihre Anzahl in deinem eigenen Chat angezeigt. Die Bewerbungen bleiben aktiv; es wird keine Gruppennachricht gesendet.")
T("When the selected bar appears", "Wann die gewählte Leiste erscheint")
T("When this bar shows, and how far it fades out of combat. Tooltips show a spell when you hover its icon. This page and MSUF Edit Mode always show every bar.", "Wann diese Leiste erscheint und wie stark sie außerhalb des Kampfes verblasst. Tooltips zeigen einen Zauber, wenn du mit der Maus auf sein Symbol zeigst. Diese Seite und der MSUF-Bearbeitungsmodus zeigen immer jede Leiste.")
T("When to remind", "Zeitpunkt der Erinnerung")
T("When to show", "Wann anzeigen")
T("Where", "Wo")
T("Where are the Suite minimap settings?", "Wo sind die Suite-Minikarten-Einstellungen?")
T("Where are the nameplate settings?", "Wo sind die Namensplaketten-Einstellungen?")
T("Where is the cooldown manager?", "Wo ist der Cooldown-Manager?")
T("Where the buff or debuff is looked for. Automatic: harmful spells on your target, all others on you.", "Wo nach dem Buff oder Debuff gesucht wird. Automatisch: schädliche Zauber auf deinem Ziel, alle anderen auf dir.")
T("Where to show recent actions", "Anzeigeort der letzten Aktionen")
T("Which Blizzard auras each kind of plate shows.", "Welche Blizzard-Auren jede Plakettenart zeigt.")
T("Which number is drawn on top when both show.", "Welche Zahl oben gezeichnet wird, wenn beide sichtbar sind.")
T("Which numbers show, which one is drawn on top, and their size and place. Single spells can differ: click them in the preview. The font settings below apply to every bar; Slug has no shadow.", "Welche Zahlen erscheinen, welche oben gezeichnet wird sowie ihre Größe und Position. Einzelne Zauber können abweichen: Klicke sie in der Vorschau an. Die Schrifteinstellungen unten gelten für jede Leiste; Slug hat keinen Schatten.")
T("Which units get nameplates and how plates share space.", "Welche Einheiten Namensplaketten bekommen und wie Plaketten sich den Platz teilen.")
T("While DataTexts and this choice are enabled, MSUF remembers this character's gold at login and after money changes. Hover a Gold or Session gold DataText to see the last known account total and up to eight other characters. No background scans are used.", "Solange DataTexts und diese Option aktiv sind, speichert MSUF das Gold dieses Charakters beim Einloggen und nach Goldänderungen. Fahre über einen Gold- oder Sitzungsgold-DataText, um den zuletzt bekannten Gesamtbetrag und bis zu acht weitere Charaktere zu sehen. Es gibt keine Hintergrundscans.")
T("While DataTexts is active, hide Blizzard's backpack and bag slots. A Bag space DataText opens the native bags when clicked. Turn this off to restore the Blizzard buttons.", "Solange das Modul Infotexte aktiv ist, werden Blizzards Rucksack- und Taschenplätze ausgeblendet. Ein Infotext „Taschenplatz“ öffnet beim Klicken die originalen Taschen. Schalte dies aus, um die Blizzard-Buttons wiederherzustellen.")
T("While a key runs, each defeated boss shows how far ahead or behind you are: against the best time you ever had on that boss, or against the boss times of your fastest completed run, at this keystone level or at any. Only runs this character completed count. With target times on, bosses still alive show the time to beat.", "Während ein Schlüssel läuft, zeigt jeder besiegte Boss, wie weit du vorn oder hinten liegst: gegenüber deiner Bestzeit an diesem Boss oder gegenüber den Bosszeiten deines schnellsten abgeschlossenen Runs, auf dieser Schlüsselsteinstufe oder auf jeder. Es zählen nur Runs, die dieser Charakter abgeschlossen hat. Mit eingeschalteten Zielzeiten zeigen noch lebende Bosse die Zeit, die es zu schlagen gilt.")
T("While the buff of this item's use lasts, the icon shows its duration and stacks instead of the cooldown.", "Solange der Stärkungszauber durch die Benutzung dieses Gegenstands wirkt, zeigt das Symbol Dauer und Stapel statt der Abklingzeit.")
T("While the buff of this spell lasts, the icon shows its duration and stacks instead of the cooldown.", "Solange der Buff dieses Zaubers anhält, zeigt das Symbol seine Dauer und Stapel statt der Abklingzeit.")
T("While this is on, move the window in MSUF Edit Mode or with the two positions below. While it is off, Blizzard's Edit Mode places it.", "Wenn aktiv, verschiebst du das Fenster im MSUF-Bearbeitungsmodus oder mit den beiden Positionseinstellungen darunter. Wenn inaktiv, bestimmt Blizzards Bearbeitungsmodus die Position.")
T("While you hold the key, a tooltip that the rules above would hide is shown.", "Solange du die Taste hältst, wird ein Tooltip angezeigt, den die obigen Regeln ausblenden würden.")
