T("Windows update from the client's own combat data: every event outside combat, and at the chosen interval during combat.", "Die Fenster aktualisieren sich aus den eigenen Kampfdaten des Clients: außerhalb des Kampfes bei jedem Ereignis, im Kampf im gewählten Intervall.")
T("Wine-black panels with dusty rose controls.", "Weinschwarze Flächen mit altrosa Bedienelementen.")
T("Wipe", "Niederlage")
T("With every selected DoT active, even a lone one, the all-DoTs color wins over individual and role colors. Otherwise individual colors follow list order.", "Sind alle ausgewählten DoTs aktiv, auch ein einzelner, hat die Farbe für alle DoTs Vorrang vor Einzel- und Rollenfarben. Sonst folgen Einzelfarben der Listenreihenfolge.")
T("Withdraw", "Abheben")
T("WoW Forever only. Lists your group's threat on the watched enemy from Blizzard's threat data, highest first; for a friendly target, its enemy is used. Values the game keeps hidden are left out. Turn the mouse wheel over the window when more members are listed than rows fit. The red mark shows where you would take aggro, which is not the point where you match the tank. The meter repaints at most five times a second and reads no combat log.", "Nur WoW Forever. Listet die Bedrohung deiner Gruppe auf dem beobachteten Gegner aus Blizzards Bedrohungsdaten auf, höchste zuerst; bei einem freundlichen Ziel wird dessen Gegner verwendet. Werte, die das Spiel verbirgt, fehlen. Drehe das Mausrad über dem Fenster, wenn mehr Mitglieder gelistet sind, als Zeilen passen. Die rote Markierung zeigt, wo du Aggro ziehen würdest; das ist nicht der Punkt, an dem du den Tank erreichst. Das Meter zeichnet höchstens fünfmal pro Sekunde neu und liest kein Kampflog.")
T("WoW Token", "WoW-Token")
